Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

(* [comment removed for export] *)
Definition FRC (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 ret))
    (Z_to_bv 64 (s - 16)) (word_to_le_bytes 8 (getr regs 8)))
    (Z_to_bv 64 (s - 24)) (word_to_le_bytes 8 (getr regs 9)))
    (Z_to_bv 64 (s - 32)) (word_to_le_bytes 8 (getr regs 18)))
    (Z_to_bv 64 (s - 40)) (word_to_le_bytes 8 (getr regs 19)))
    (Z_to_bv 64 (s - 48)) (word_to_le_bytes 8 (getr regs 20)))
    (Z_to_bv 64 (s - 80)) (word_to_le_bytes 8 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 88)) (word_to_le_bytes 8 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 96)) (word_to_le_bytes 8 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 104)) (word_to_le_bytes 8 (Z_to_bv 64 0)).
(* [comment removed for export] *)
Definition CW8 (m : word -> option byte) (p v : Z) : word -> option byte := wbytes m (Z_to_bv 64 p) (word_to_le_bytes 8 (Z_to_bv 64 v)).

Section Segs.
Context {fx : FPState}.
Variable rom : word -> option byte.
Ltac sok_in SOK :=
  store_ok_peel;
  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].
Ltac fin := repeat split; gres; pin; try reflexivity; try (apply bv_eq; reflexivity); try solve_regs_agree.

(* [comment removed for export] *)
Lemma cs_A_h : forall regs m (s pix1 : Z) (ret : word),
  (112 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pix1)%Z -> (pix1 + 64 < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 112)) 112 = true ->
  rdn SEGS (FRC m s ret regs) (Z_to_bv 64 (pix1 + 8)) 4 = Some (Z_to_le_bytes 4 1) ->
  rdn SEGS (FRC m s ret regs) (Z_to_bv 64 0x1137e8) 4 = Some (Z_to_le_bytes 4 1) ->
  getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pix1 -> getr regs 11 = Z_to_bv 64 pix1 ->
  getr regs 12 = Z_to_bv 64 30 -> getr regs 13 = Z_to_bv 64 1 ->
  exists regs',
    msteps SEGS (mkst regs (0x91ff4 : word) m rom) (mkst regs' (0x90f1c : word) (FRC m s ret regs) rom)
    /\ getr regs' 2 = Z_to_bv 64 (s - 112)
    /\ getr regs' 1 = Z_to_bv 64 0x92140
    /\ getr regs' 8 = Z_to_bv 64 pix1
    /\ getr regs' 9 = Z_to_bv 64 2
    /\ getr regs' 18 = Z_to_bv 64 30
    /\ getr regs' 19 = Z_to_bv 64 1
    /\ getr regs' 20 = Z_to_bv 64 pix1
    /\ getr regs' 10 = Z_to_bv 64 30
    /\ getr regs' 11 = Z_to_bv 64 1
    /\ getr regs' 12 = Z_to_bv 64 (s - 80)
    /\ getr regs' 13 = Z_to_bv 64 (s - 88)
