Lemma cs_H : forall regs m (s : Z),
  (112 <= s)%Z -> (s < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 112) ->
  exists regs',
    msteps SEGS (mkst regs (0x92364 : word) m rom) (mkst regs' (0x6cb3c : word) m rom)
    /\ getr regs' 1 = Z_to_bv 64 0x9236c
    /\ getr regs' 10 = Z_to_bv 64 (s - 64)
    /\ regs_agree (fun r => In r [1; 10]%list) regs regs'.
Proof.
